        else:
            if current_word:
                word = ''.join(current_word)
                if word not in seen:
                    seen.add(word)
                    words.append(word)
                current_word = []
    # Check last word
    if current_word:
        word = ''.join(current_word)
        if word not in seen:
            words.append(word)
    return words

